const body = $input.first().json.body || $input.first().json;
let machineId = (body.machine_id || '').trim();
machineId = machineId.replace(/[^A-Za-z0-9_-]/g, '');
return { json: { machine_id: machineId } };

const rows = $input.first().json || [];
const arr = Array.isArray(rows) ? rows : [rows];
let text = '';
if (arr.length === 0) {
  text = '暂无产量数据';
} else {
  text = arr.map(r => `${r.machine_id || '全厂'}: ${r.lot_count || 0}个Lot, ${r.total_wafers || 0}片晶圆`).join('\n');
}
return { json: { yield_stats: arr, summary: text } };
